const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
$tests=@(
 'https://talk.collegeconfidential.com/',
 'https://www.thestudentroom.co.uk/'
)
foreach($u in $tests){
  $code = curl.exe -s -o NUL -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 25 --compressed $u
  Write-Output "$code  $u"
}
`;
const [r1, r2] = await Promise.all([
  tools.pwsh({ description: "Probe CC and TSR", command: cmd, timeoutMs: 120000 }),
]);
console.log(r1.kind === 'foreground' ? r1.stdout.text + "|ERR:" + r1.stderr.text : JSON.stringify(r1));
